import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../utils/api';
import PhotoFrame from './PhotoFrame';
import { saveUserSession } from '../utils/session';

const Registration = () => {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  
  const [formData, setFormData] = useState({
    cnicBform: '',
    firstName: '',
    lastName: '',
    category: '',
    region: '',
    location: '',
    classLevel: 'N/A',
    photo: null
  });

  const regions = ['South', 'RSDU Hunza', 'RSDU Gilgit', 'Central Office', 'South Office'];
  
  const locationsByRegion = {
    'South': ['AKHSS Kharadar', 'Diamond Jubilee High School', 'Sultan Mohamed Shah Aga Khan School'],
    'RSDU Hunza': ['AKESP Hunza Office', 'Aga Khan School Gulmit', 'Aga Khan School Aliabad'],
    'RSDU Gilgit': ['AKESP Gilgit Office', 'Aga Khan School Gilgit', 'Diamond Jubilee School Gilgit'],
    'Central Office': ['AKESP Central Office'],
    'South Office': ['AKESP South Office']
  };

  const classes = ['PPI', 'PPII', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'N/A'];

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
      ...(name === 'region' && { location: '' }),
      ...(name === 'category' && value !== 'Student' && { classLevel: 'N/A' })
    }));
    setError('');
  };

  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        setError('Photo size should not exceed 5MB');
        return;
      }
      setFormData(prev => ({ ...prev, photo: file }));
    }
  };

  const validateStep = () => {
    setError('');
    
    switch(step) {
      case 1:
        if (!formData.cnicBform || formData.cnicBform.length !== 13) {
          setError('Please enter a valid 13-digit CNIC/B-Form number');
          return false;
        }
        break;
      case 2:
        if (!formData.firstName || !formData.lastName || !formData.category) {
          setError('Please fill in all required fields');
          return false;
        }
        break;
      case 3:
        if (!formData.region || !formData.location) {
          setError('Please select region and location');
          return false;
        }
        break;
      case 4:
        if (formData.category === 'Student' && formData.classLevel === 'N/A') {
          setError('Please select your class');
          return false;
        }
        break;
      default:
        break;
    }
    return true;
  };

  const handleNext = async () => {
    if (!validateStep()) return;

    if (step === 1) {
      // Check if CNIC already exists
      setLoading(true);
      try {
        const response = await authAPI.checkCNIC(formData.cnicBform);
        if (response.data.exists) {
          setError('This CNIC/B-Form is already registered. Please login instead.');
          setLoading(false);
          return;
        }
      } catch (err) {
        setError('Error checking CNIC. Please try again.');
        setLoading(false);
        return;
      }
      setLoading(false);
    }

    if (step < 5) {
      setStep(step + 1);
    }
  };

  const handleBack = () => {
    if (step > 1) {
      setStep(step - 1);
      setError('');
    }
  };

  const handleSubmit = async () => {
    setLoading(true);
    setError('');

    try {
      const data = new FormData();
      data.append('cnicBform', formData.cnicBform);
      data.append('firstName', formData.firstName);
      data.append('lastName', formData.lastName);
      data.append('category', formData.category);
      data.append('region', formData.region);
      data.append('location', formData.location);
      data.append('classLevel', formData.classLevel);
      if (formData.photo) {
        data.append('photo', formData.photo);
      }

      const response = await authAPI.register(data);
      
      saveUserSession(response.data.user);
      
      // Navigate to dashboard
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Registration failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const renderStep = () => {
    switch(step) {
      case 1:
        return (
          <div>
            <h2 style={{ marginBottom: '20px', color: '#333' }}>Step 1: Create Your ID</h2>
            <div className="form-group">
              <label>B-Form or CNIC Number *</label>
              <input
                type="text"
                name="cnicBform"
                value={formData.cnicBform}
                onChange={handleInputChange}
                placeholder="Enter 13-digit number"
                maxLength="13"
                pattern="[0-9]*"
              />
              <small style={{ color: '#666', fontSize: '0.9rem' }}>
                Enter your 13-digit B-Form or CNIC number without dashes
              </small>
            </div>
          </div>
        );

      case 2:
        return (
          <div>
            <h2 style={{ marginBottom: '20px', color: '#333' }}>Step 2: Basic Details</h2>
            <div className="form-group">
              <label>First Name *</label>
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleInputChange}
                placeholder="Enter your first name"
              />
            </div>
            <div className="form-group">
              <label>Last Name *</label>
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleInputChange}
                placeholder="Enter your last name"
              />
            </div>
            <div className="form-group">
              <label>Category *</label>
              <select
                name="category"
                value={formData.category}
                onChange={handleInputChange}
              >
                <option value="">Select Category</option>
                <option value="Student">Student</option>
                <option value="Staff">Staff</option>
                <option value="Teacher">Teacher</option>
                <option value="Other">Other</option>
              </select>
            </div>
          </div>
        );

      case 3:
        return (
          <div>
            <h2 style={{ marginBottom: '20px', color: '#333' }}>Step 3: Location Details</h2>
            <div className="form-group">
              <label>Region *</label>
              <select
                name="region"
                value={formData.region}
                onChange={handleInputChange}
              >
                <option value="">Select Region</option>
                {regions.map(region => (
                  <option key={region} value={region}>{region}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>School/Office *</label>
              <select
                name="location"
                value={formData.location}
                onChange={handleInputChange}
                disabled={!formData.region}
              >
                <option value="">Select Location</option>
                {formData.region && locationsByRegion[formData.region].map(location => (
                  <option key={location} value={location}>{location}</option>
                ))}
              </select>
            </div>
          </div>
        );

      case 4:
        return (
          <div>
            <h2 style={{ marginBottom: '20px', color: '#333' }}>Step 4: Class Selection</h2>
            <div className="form-group">
              <label>Class {formData.category === 'Student' ? '*' : '(Optional)'}</label>
              <select
                name="classLevel"
                value={formData.classLevel}
                onChange={handleInputChange}
                disabled={formData.category !== 'Student'}
              >
                <option value="">Select Class</option>
                {classes.map(cls => (
                  <option key={cls} value={cls}>{cls}</option>
                ))}
              </select>
              {formData.category !== 'Student' && (
                <small style={{ color: '#666', fontSize: '0.9rem' }}>
                  Class selection is only for students
                </small>
              )}
            </div>
          </div>
        );

      case 5:
        return (
          <div>
            <h2 style={{ marginBottom: '20px', color: '#333' }}>Step 5: Upload Photo (Optional)</h2>
            <div className="form-group">
              <label>Profile Photo</label>
              <input
                type="file"
                accept="image/jpeg,image/jpg,image/png"
                onChange={handlePhotoChange}
              />
              <small style={{ color: '#666', fontSize: '0.9rem', display: 'block', marginTop: '5px' }}>
                Upload a photo to create your personalized reading frame (Max 5MB)
              </small>
            </div>
            
            {formData.photo && (
              <PhotoFrame 
                photo={formData.photo}
                userName={`${formData.firstName} ${formData.lastName}`}
                location={formData.location}
              />
            )}

            <div style={{ 
              background: '#f8f9fa', 
              padding: '20px', 
              borderRadius: '10px',
              marginTop: '20px'
            }}>
              <h3 style={{ marginBottom: '15px', color: '#333' }}>Review Your Information</h3>
              <div style={{ lineHeight: '1.8' }}>
                <p><strong>Name:</strong> {formData.firstName} {formData.lastName}</p>
                <p><strong>Category:</strong> {formData.category}</p>
                <p><strong>Region:</strong> {formData.region}</p>
                <p><strong>Location:</strong> {formData.location}</p>
                <p><strong>Class:</strong> {formData.classLevel}</p>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div>
      <div className="header">
        <div className="header-content">
          <h1>📝 Registration</h1>
          <p>Gift of Reading Initiative</p>
        </div>
      </div>

      <div className="container">
        <div className="card" style={{ maxWidth: '600px', margin: '0 auto' }}>
          {/* Progress Indicator */}
          <div style={{ marginBottom: '30px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
              {[1, 2, 3, 4, 5].map(num => (
                <div
                  key={num}
                  style={{
                    width: '40px',
                    height: '40px',
                    borderRadius: '50%',
                    background: step >= num ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : '#e0e0e0',
                    color: step >= num ? 'white' : '#999',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontWeight: 'bold',
                    fontSize: '1.1rem'
                  }}
                >
                  {num}
                </div>
              ))}
            </div>
            <div className="progress-bar" style={{ height: '8px' }}>
              <div 
                className="progress-fill" 
                style={{ width: `${(step / 5) * 100}%` }}
              />
            </div>
          </div>

          {error && <div className="error">{error}</div>}

          {renderStep()}

          <div style={{ 
            display: 'flex', 
            gap: '10px', 
            marginTop: '30px',
            justifyContent: step > 1 ? 'space-between' : 'flex-end'
          }}>
            {step > 1 && (
              <button 
                className="btn btn-secondary" 
                onClick={handleBack}
                disabled={loading}
              >
                ← Back
              </button>
            )}
            {step < 5 ? (
              <button 
                className="btn" 
                onClick={handleNext}
                disabled={loading}
              >
                {loading ? 'Processing...' : 'Next →'}
              </button>
            ) : (
              <button 
                className="btn" 
                onClick={handleSubmit}
                disabled={loading}
              >
                {loading ? 'Registering...' : 'Complete Registration ✓'}
              </button>
            )}
          </div>

          <div style={{ marginTop: '20px', textAlign: 'center' }}>
            <button
              onClick={() => navigate('/')}
              style={{
                background: 'none',
                border: 'none',
                color: '#667eea',
                cursor: 'pointer',
                textDecoration: 'underline'
              }}
            >
              ← Back to Home
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Registration;
